package mcshim;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URL;

/**
 * Network calls the game makes, redirected here by the remapper. Indev asks
 * minecraft.net whether the player is signed in ("?n=name&i=session") before
 * it will use a level it has just generated; that site is gone, so the answer
 * is given here.
 */
public final class Net {
    private Net() {}

    /**
     * Indev's Load / Save level screens ask minecraft.net for the player's five
     * online level slots and show the "Load file..." / "Save file..." buttons
     * only once that list arrives. Answer "five empty slots".
     */
    public static java.net.URLConnection openConnection(final URL url) throws IOException {
        if (url.toString().contains("/listmaps.jsp?")) {
            return new java.net.URLConnection(url) {
                public void connect() {}
                public InputStream getInputStream() throws IOException {
                    return new ByteArrayInputStream("-;-;-;-;-\n".getBytes("UTF-8"));
                }
            };
        }
        return url.openConnection();
    }

    public static InputStream openStream(URL url) throws IOException {
        String s = url.toString();
        if (s.contains("minecraft.net/") && s.contains("?n=") && s.contains("&i=")) {
            return new ByteArrayInputStream("1\n".getBytes("UTF-8"));
        }
        if (s.equals("http://www.minecraft.net/resources/")) return resourceList();
        if (s.contains("minecraft.net/game/joinserver.jsp?")) {
            // Alpha's online-mode handshake: answer it with the signed-in account
            // through today's session server (the game's session id is a dummy)
            String id = query(s, "serverId");
            boolean ok = id != null && Platform.get().joinServer(id);
            return new ByteArrayInputStream((ok ? "ok" : "Not signed in to a Minecraft account") .getBytes("UTF-8"));
        }
        return url.openStream();
    }

    private static String query(String url, String key) {
        int q = url.indexOf('?');
        if (q < 0) return null;
        for (String kv : url.substring(q + 1).split("&")) {
            int e = kv.indexOf('=');
            if (e > 0 && kv.substring(0, e).equals(key)) {
                try { return java.net.URLDecoder.decode(kv.substring(e + 1), "UTF-8"); } catch (Exception x) { return null; }
            }
        }
        return null;
    }

    /**
     * Indev only uses the sounds listed by minecraft.net/resources/ ("path,size,date"
     * per line), checking each against .minecraft/resources. List what is already
     * there so the game takes the installed files as up to date.
     */
    private static InputStream resourceList() throws IOException {
        java.io.File root = new java.io.File(System.getProperty("user.home"), ".minecraft/resources");
        placeholderMusic(root);
        StringBuilder sb = new StringBuilder();
        list(root, "", sb);
        Platform.get().log("resource list for Indev: " + sb.length() + " bytes from " + root);
        return new ByteArrayInputStream(sb.toString().getBytes("UTF-8"));
    }

    /**
     * Indev plays "calm" music non-stop and fails every tick when there is none.
     * Without real music, install 30 s of silence as music/calm0.ogg; remove it
     * again once real calm*.ogg files are there.
     */
    private static void placeholderMusic(java.io.File root) {
        java.io.File ph = new java.io.File(root, "music/calm0.ogg");
        boolean real = false;
        for (String d : new String[] {"music", "newmusic"}) {
            String[] names = new java.io.File(root, d).list();
            if (names != null) for (String n : names) if (n.startsWith("calm") && !n.equals("calm0.ogg")) real = true;
        }
        if (real) { ph.delete(); return; }
        if (ph.exists()) return;
        try {
            ph.getParentFile().mkdirs();
            java.io.FileOutputStream o = new java.io.FileOutputStream(ph);
            o.write(base64(SILENCE));
            o.close();
        } catch (IOException e) {
            Platform.get().log("music placeholder: " + e);
        }
    }

    private static byte[] base64(String s) {
        String a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        java.io.ByteArrayOutputStream o = new java.io.ByteArrayOutputStream();
        int buf = 0, bits = 0;
        for (int i = 0; i < s.length(); i++) {
            int v = a.indexOf(s.charAt(i));
            if (v < 0) continue;
            buf = (buf << 6) | v; bits += 6;
            if (bits >= 8) { bits -= 8; o.write((buf >> bits) & 0xff); }
        }
        return o.toByteArray();
    }

    private static final String SILENCE = "";

    private static void list(java.io.File dir, String prefix, StringBuilder sb) {
        java.io.File[] fs = dir.listFiles();
        if (fs == null) return;
        java.util.Arrays.sort(fs);
        for (java.io.File f : fs) {
            if (f.isDirectory()) list(f, prefix + f.getName() + "/", sb);
            else if (prefix.length() > 0) sb.append(prefix).append(f.getName()).append(',').append(f.length()).append(",0\n");
        }
    }
}
